/// <summary>
/// CB166_SalesOrderSubstitutes
/// Post sales order creation processing multithread batch task
/// inspired from new class LedgerJournalBatchPost
/// </summary>
class METSysMessageProcessorTaskService extends SysOperationServiceBase
{    
    boolean isExecutingInBatch, isMainBatchTask;
    SysMessageQueue messageQueue;
    SysMessageRecId messageRecId;
    SysMessageProcessorBatchAffinity            affinity;
    UserConnection                  secondConnection;
    int counter;
    guid topPickingProcessId;

}

Method.Source:
protected void initialise()
{
    secondConnection   = new UserConnection();
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METPostSalesOrderCreationProcessingContract</c>.
/// </param>
public void process(METSysMessageProcessorContract _contract)
{
    messageQueue = _contract.parmMessageQueue();
    isMainBatchTask    = _contract.parmIsMainBatchTask();
    topPickingProcessId = _contract.parmTopPickingProcessId();

    this.initialise();

    this.processTask(true);

    if (isMainBatchTask)
    {
        //last run of main task thread to make sure all others have been processed
        this.processTask(false);
    }
}

/// <summary>
/// Process the batch tasks.
/// </summary>
/// <param name = "_readPast">Read past table setting.</param>
public void processTask(boolean _readPast)
{         
    while (this.getMessageFromQueue(_readPast))
    {
        try
        {              
            if (this.messageRecId)
            {
                this.execute(this.messageRecId);
            }                
        }
        catch (Exception::Error)
        {
            // Catch any exception so that any one error won't bring down
            // the entire process of sales order substitution.
            Global::exceptionTextFallThrough();
        }
    }        
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_salesId">Sales order to substitute.</param>
private boolean execute(SysMessageRecId _messageRecId)
{
    boolean ret;       
    UserConnection                              bundleConnection;
    SysMessageQueueMetadata                     messageQueueMetadata;
    METSysMessageProcessorTaskErrorState        lastErrorState;
    SysMessage                                  message;

    #OCCRetryCount

    boolean failed;
    boolean isInMessageProcessing = false;
    boolean isInMessageCancellation = false;

    SysMessageProcessorMessageLog log;
    List processedLog = new List(Types::Record);
    List failedDependencyLog = new List(Types::Record);
    RecordInsertList recordInsertList = new RecordInsertList(tableNum(SysMessageProcessorMessageLog));

    try
    {
        ttsbegin;

        isInMessageProcessing = false;
        isInMessageCancellation = false;

        //Array recordArray = rowListEnumerator.current();
        //SysMessageProcessorTaskBundleMessage bundleMessage = recordArray.value(SysMessageProcessorTaskBundleMessageTable);
        SysMessageProcessorTaskBundleMessage bundleMessage;
        bundleMessage.NextState = SysMessageState::Processed;
        //SysMessage message = recordArray.value(SysMessageTable);
        message = SysMessage::find(_messageRecId);
        //SysMessageProcessingState messageProcessingState = recordArray.value(SysMessageProcessingStateTable);
        SysMessageProcessingState messageProcessingState = SysMessageProcessingState::find(_messageRecId);

        if (messageProcessingState.State == SysMessageState::Failed)
        {
            failed = log.Result != SysMessageProcessingResult::Processed;
            return false;
        }

        infolog.clear();
        log = this.createLog(message, bundleMessage.NextState);

        if (bundleMessage.NextState == SysMessageState::Processed)
        {
            isInMessageProcessing = true;

            this.executeStateTransition(message, SysMessageState::Processed);

            log.result(SysMessageProcessingResult::Processed);
            processedLog.addEnd(log);
            //activityContext.addCustomProperty(fieldStr(SysMessageProcessorMessageLog, Result), enum2Symbol(enumNum(SysMessageProcessingResult), SysMessageProcessingResult::Processed));
        }
        else if (bundleMessage.NextState == SysMessageState::Cancelled)
        {
            isInMessageCancellation = true;

            this.executeStateTransition(message, SysMessageState::Cancelled, true);

            log.result(SysMessageProcessingResult::Cancelled);
            processedLog.addEnd(log);
            //activityContext.addCustomProperty(fieldStr(SysMessageProcessorMessageLog, Result), enum2Symbol(enumNum(SysMessageProcessingResult), SysMessageProcessingResult::Cancelled));
        }
        else
        {
            throw error(Error::wrongUseOfFunction(funcName()));
        }

        failed = false;

        this.addLogToRecordInsertList(processedLog.getEnumerator(), recordInsertList);
        this.addLogToRecordInsertList(failedDependencyLog.getEnumerator(), recordInsertList);
        recordInsertList.insertDatabase();

        this.updateMessageStateToDesiredNextState(processedLog.elements());

        ttscommit;
    }
    catch (Exception::DuplicateKeyException)
    {
        lastErrorState = METSysMessageProcessorTaskErrorState::construct(
                //rowListEnumerator.current(),
                message,
                log,
                processedLog,
                failedDependencyLog,
                recordInsertList,
                isInMessageProcessing,
                isInMessageCancellation);

        throw Exception::DuplicateKeyException;
    }
    catch (Exception::UpdateConflict)
    {
        lastErrorState = METSysMessageProcessorTaskErrorState::construct(
                //rowListEnumerator.current(),
                message,
                log,
                processedLog,
                failedDependencyLog,
                recordInsertList,
                isInMessageProcessing,
                isInMessageCancellation);

        throw Exception::UpdateConflict;
    }
    catch (Exception::Deadlock)
    {
        lastErrorState = METSysMessageProcessorTaskErrorState::construct(
                //rowListEnumerator.current(),
                message,
                log,
                processedLog,
                failedDependencyLog,
                recordInsertList,
                isInMessageProcessing,
                isInMessageCancellation);

        throw Exception::Deadlock;
    }
    catch (Exception::TransientSqlConnectionError)
    {
        lastErrorState = METSysMessageProcessorTaskErrorState::construct(
                //rowListEnumerator.current(),
                message,
                log,
                processedLog,
                failedDependencyLog,
                recordInsertList,
                isInMessageProcessing,
                isInMessageCancellation);

        throw Exception::TransientSqlConnectionError;
    }
    catch
    {
        failed = true;

        METSysMessageProcessorTaskErrorState errorState = METSysMessageProcessorTaskErrorState::construct(
                //rowListEnumerator.current(),
                message,
                log,
                processedLog,
                failedDependencyLog,
                recordInsertList,
                isInMessageProcessing,
                isInMessageCancellation);

        this.onMessageProcessingUnrecoverableError(errorState);
    }

    return true;
}

/// <summary>
/// Get sales order id to substitute from the top picking queue <c>METPostSalesOrderCreationProcessingQueue</c>
/// </summary>
/// <param name = "_processId">Guid created and added in the contract <c>METPostSalesOrderCreationProcessingContract</c></param>
/// <param name = "_readPast">boolean to read past records or not</param>
/// <returns>Get sales order id to substitute</returns>
private SysMessageRecId getMessageFromQueue(boolean _readPast)
{
    METPEPricingTopPickingQueue pricingTopPickingQueue;

    #OCCRetryCount
    int backOffWait;
    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    pricingTopPickingQueue.readPast(_readPast);

    try
    {
        ttsbegin;

        select firstonly pessimisticlock MessageRecId                
        from pricingTopPickingQueue
        where pricingTopPickingQueue.ProcessId == topPickingProcessId;

        if (pricingTopPickingQueue.MessageRecId)
        {
            this.messageRecId = pricingTopPickingQueue.MessageRecId;
            pricingTopPickingQueue.delete();
        }
        else
        {
            // no sales order id found from top picking queue
            this.messageRecId = 0;
        }

        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return this.messageRecId;


}

private SysMessageProcessorMessageLog createLog(SysMessage _message, SysMessageState _nextState)
{
    SysMessageProcessorMessageLog log1 = SysMessageProcessorMessageLog::createLog(_message, _nextState);
    log1.BatchAffinity = affinity;

    return log1;
}

private void executeStateTransition(SysMessage _message, SysMessageState _nextState, boolean _skipTransitionValidation = false)
{
    SysMessageTypeMetadata messageTypeMetadata = SysMessageTypeMetadata::construct(_message.MessageType);
    //METPEPricingMessageType messageTypeMetadata = SysMessageTypeMetadata::construct(_message.MessageType);

    if (_skipTransitionValidation || messageTypeMetadata.metAllowStateTransition(_message, _nextState))
    {
        SysMessageTarget messageTarget = SysMessageTarget::find(_message.MessageTarget);
        SysMessageTargetInstanceTypeMetadata messageTargetInstanceType = SysMessageTargetInstanceTypeMetadata::construct(messageTarget.InstanceRelationType);
        CompanyId companyId = messageTargetInstanceType.getCompanyId(messageTarget);

        if (companyId)
        {
            changecompany (companyId)
            {
                messageTypeMetadata.processMessageStateTransition(_message, SysMessageStateTransition::newFromStates(_message.messageProcessingState().State, _nextState));
            }
        }
        else
        {
            messageTypeMetadata.processMessageStateTransition(_message, SysMessageStateTransition::newFromStates(_message.messageProcessingState().State, _nextState));
        }
    }
    else
    {
        throw Error(strFmt("@MessageProcessor:Error_RequestedStateTransitionNotAllowed", _message.RecId));
    }
}

private void updateMessageStateToDesiredNextState(int64 _expectedUpdateCount)
{
    SysMessageProcessingState       messageProcessingState;
    SysMessageProcessorMessageLog   messageLog;

    update_recordset messageProcessingState
        setting State = messageLog.NextState
        where messageProcessingState.State == SysMessageState::Queued
        join messageLog
        where messageLog.Message == messageProcessingState.Message
           && (messageLog.Result == SysMessageProcessingResult::Processed || messageLog.Result == SysMessageProcessingResult::Cancelled)
           && messageLog.CreatedTransactionId == appl.curTransactionId();

    if (_expectedUpdateCount != messageProcessingState.RowCount())
    {
        throw Exception::UpdateConflict;
    }
}

/// <summary>
/// Bug 394695: [MS-MET] SysMessageProcessorTask.processBundle - Error logging
/// Copied from SysMessageProcessorTask and removed bundleMessage, activityContext and logMessageProcessorReachesFailCountLimitDuringMessageProcessing as it is only processing activityContext
/// </summary>
/// <param name = "_errorState">Error state</param>
private void onMessageProcessingUnrecoverableError(METSysMessageProcessorTaskErrorState _errorState)
{
    #OCCRetryCount

    /*Array recordArray = _errorState.getRecordArray();

    SysMessageProcessorTaskBundleMessage bundleMessage = recordArray.value(SysMessageProcessorTaskBundleMessageTable);
    SysMessage message = recordArray.value(SysMessageTable);
    SysMessageProcessingState messageProcessingState = recordArray.value(SysMessageProcessingStateTable);*/

    SysMessage message = _errorState.getMessage();
    SysMessageProcessingState messageProcessingState = SysMessageProcessingState::find(message.RecId);

    /*using (SysInstrumentationActivityContext activityContext = instrumentationLogger.messageProcessorTask().messageProcessingUnrecoverableError(
        message,
        bundleMessage,
        _errorState.getIsExceptionDuringMessageProcessing(),
        _errorState.getIsExceptionDuringMessageCancellation()))
    {*/
        try
        {
            ttsbegin;

            this.logMessageProcessingError(
                _errorState.getLog(),
                _errorState.getProcessedLog(),
                _errorState.getFailedDependencyLog(),
                _errorState.getRecordInsertList());

            if (_errorState.getIsExceptionDuringMessageProcessing())
            {
                this.incrementFailCountOnMessageProcessingState(messageProcessingState);

                SysMessageState desiredMessageState = this.nextMessageStateAfterFailure(message, messageProcessingState.FailCount + 1);

                if (desiredMessageState == SysMessageState::Failed)
                {
                    //this.logMessageProcessorReachesFailCountLimitDuringMessageProcessing(message, activityContext, desiredMessageState);
                    this.markMessageAs(messageProcessingState, desiredMessageState);
                    this.sendMessageProcessedBusinessEvent(message, messageProcessingState, _errorState.getLog());
                }
                else if (desiredMessageState == SysMessageState::Cancelled)
                {
                    //this.logMessageProcessorReachesFailCountLimitDuringMessageProcessing(message, activityContext, desiredMessageState);
                    this.executeStateTransition(message, SysMessageState::Cancelled, true);
                    this.markMessageAs(messageProcessingState, desiredMessageState);
                    this.sendMessageProcessedBusinessEvent(message, messageProcessingState, _errorState.getLog());
                }
                else if (desiredMessageState != SysMessageState::Queued)
                {
                    throw error(Error::wrongUseOfFunction(funcName()));
                }
            }
            else if (_errorState.getIsExceptionDuringMessageCancellation())
            {
                SysMessageState desiredMessageState = this.nextMessageStateAfterFailure(message, messageProcessingState.FailCount + 1);

                //this.logMessageProcessorReachesFailCountLimitDuringMessageCancellation(message, activityContext, desiredMessageState);

                this.markMessageAs(messageProcessingState, desiredMessageState);
            }

            ttscommit;
        }
        catch (Exception::UpdateConflict)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                this.onExceptionDuringExceptionHandling(_errorState);
            }
            retry;
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                this.onExceptionDuringExceptionHandling(_errorState);
            }
            retry;
        }
        catch (Exception::TransientSqlConnectionError)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                this.onExceptionDuringExceptionHandling(_errorState);
            }
            retry;
        }
        catch
        {
            this.onExceptionDuringExceptionHandling(_errorState);
        }
    //}
}

/// <summary>
/// Bug 394695: [MS-MET] SysMessageProcessorTask.processBundle - Error logging
/// Copied from SysMessageProcessorTask and removed bundleMessage and activityContext
/// </summary>
/// <param name = "_errorState">Error state</param>
private void onExceptionDuringExceptionHandling(METSysMessageProcessorTaskErrorState _errorState)
{
    /*Array recordArray = _errorState.getRecordArray();

    SysMessageProcessorTaskBundleMessage bundleMessage = recordArray.value(SysMessageProcessorTaskBundleMessageTable);
    SysMessage message = recordArray.value(SysMessageTable);
    SysMessageProcessingState messageProcessingState = recordArray.value(SysMessageProcessingStateTable);*/

    SysMessage message = _errorState.getMessage();
    SysMessageProcessingState messageProcessingState = SysMessageProcessingState::find(message.RecId);

    /*using (SysInstrumentationActivityContext activityContext = instrumentationLogger.messageProcessorTask().messageProcessingUnrecoverableError(
        message,
        bundleMessage,
        _errorState.getIsExceptionDuringMessageProcessing(),
        _errorState.getIsExceptionDuringMessageCancellation()))
    {*/
        ttsbegin;

        //activityContext.addCustomProperty('IsExceptionDuringExceptionHandling', 'true');

        this.logMessageProcessingError(
            _errorState.getLog(),
            _errorState.getProcessedLog(),
            _errorState.getFailedDependencyLog(),
            _errorState.getRecordInsertList());

        if (_errorState.getIsExceptionDuringMessageProcessing())
        {
            this.incrementFailCountOnMessageProcessingState(messageProcessingState);
        }

        // when exception happens during handle exception in message type we don't want to try anymore
        // to avoid a situation when many "cleanup" tasks waste resources with low chance to ever succeed.
        SysMessageState desiredMessageState = this.nextMessageStateAfterFailure(message, messageProcessingState.FailCount + 1);

        /*if (desiredMessageState == SysMessageState::Failed || desiredMessageState == SysMessageState::Cancelled)
        {
            this.logMessageProcessorReachesFailCountLimit(message, activityContext, desiredMessageState);
        }*/

        this.markMessageAs(messageProcessingState, desiredMessageState);
        this.sendMessageProcessedBusinessEvent(message, messageProcessingState, _errorState.getLog());

        ttscommit;
    //}
}

/// <summary>
/// Bug 394695: [MS-MET] SysMessageProcessorTask.processBundle - Error logging
/// Copied from SysMessageProcessorTask
/// </summary>
/// <param name = "_log">Log</param>
/// <param name = "_processedLog">Processed log</param>
/// <param name = "_failedDependencyLog">Failed dependency log</param>
/// <param name = "_recordInsertList">Record insert list</param>
private void logMessageProcessingError(SysMessageProcessorMessageLog _log, List _processedLog, List _failedDependencyLog, RecordInsertList _recordInsertList)
{
    _log.result(SysMessageProcessingResult::Failed);
    _recordInsertList.add(_log);

    this.addLogToRecordInsertList(_failedDependencyLog.getEnumerator(), _recordInsertList);
    this.addRolledBackToRecordInsertList(_processedLog.getEnumerator(), _recordInsertList);
    _recordInsertList.insertDatabase();
}

/// <summary>
/// Bug 394695: [MS-MET] SysMessageProcessorTask.processBundle - Error logging
/// Copied from SysMessageProcessorTask
/// </summary>
/// <param name = "_enumerator">Processed log</param>
/// <param name = "_recordInsetList">Record insert list</param>
private void addRolledBackToRecordInsertList(ListEnumerator _enumerator, RecordInsertList _recordInsetList)
{
    while (_enumerator.moveNext())
    {
        SysMessageProcessorMessageLog rolledBackLog = _enumerator.current();
        rolledBackLog.Result = SysMessageProcessingResult::RolledBack;
        _recordInsetList.add(rolledBackLog);
    }
}

/// <summary>
/// Bug 394695: [MS-MET] SysMessageProcessorTask.processBundle - Error logging
/// Copied from SysMessageProcessorTask
/// </summary>
/// <param name = "_messageProcessingState">Processing state</param>
private void incrementFailCountOnMessageProcessingState(SysMessageProcessingState _messageProcessingState)
{
    SysMessageProcessingState messageProcessingState;

    update_recordset messageProcessingState
        setting FailCount = messageProcessingState.FailCount + 1
            where messageProcessingState.RecId == _messageProcessingState.RecId
               && messageProcessingState.FailCount == _messageProcessingState.FailCount;

    if (messageProcessingState.RowCount() != 1)
    {
        throw Exception::UpdateConflict;
    }
}

/// <summary>
/// Bug 394695: [MS-MET] SysMessageProcessorTask.processBundle - Error logging
/// Copied from SysMessageProcessorTask
/// </summary>
/// <param name = "_messageProcessingState">Processing state</param>
/// <param name = "_messageState">State</param>
private void markMessageAs(SysMessageProcessingState _messageProcessingState, SysMessageState _messageState)
{
    SysMessageProcessingState messageProcessingState;

    update_recordset messageProcessingState
        setting State = _messageState
            where messageProcessingState.RecId == _messageProcessingState.RecId
               && messageProcessingState.State == SysMessageState::Queued;

    if (messageProcessingState.RowCount() != 1)
    {
        throw Exception::UpdateConflict;
    }

    // Update the buffer without the need to re-read it from the database.
    _messageProcessingState.State = _messageState;
}

/// <summary>
/// Bug 394695: [MS-MET] SysMessageProcessorTask.processBundle - Error logging
/// Copied from SysMessageProcessorTask
/// </summary>
/// <param name = "_message">Message</param>
/// <param name = "_messageProcessingState">State</param>
/// <param name = "_messageProcessorMessageLog">Log</param>
private void sendMessageProcessedBusinessEvent(
    SysMessage                      _message,
    SysMessageProcessingState       _messageProcessingState,
    SysMessageProcessorMessageLog   _messageProcessorMessageLog)
{
    if (this.mustSendMessageProcessedBusinessEvent(_message))
    {
        SysMessageProcessorMessageProcessedBusinessEvent::newFromMessage(_message, _messageProcessingState, _messageProcessorMessageLog).send();
    }
}

/// <summary>
/// Bug 394695: [MS-MET] SysMessageProcessorTask.processBundle - Error logging
/// Copied from SysMessageProcessorTask
/// </summary>
/// <param name = "_message">Message</param>
/// <returns>True if the message processed business event must be sent, otherwise false</returns>
private boolean mustSendMessageProcessedBusinessEvent(SysMessage _message)
{
    SysMessageTypeMetadata messageTypeMetadata = SysMessageTypeMetadata::construct(_message.MessageType);

    return messageTypeMetadata.mustSendMessageProcessedBusinessEvent();
}

/// <summary>
/// Bug 394695: [MS-MET] SysMessageProcessorTask.processBundle - Error logging
/// Copied from SysMessageProcessorTask
/// </summary>
/// <param name = "_message">Message</param>
/// <param name = "_countOfFailedExecutionAttempts">Count of failed execution attempts</param>
/// <returns>Next message state after failure</returns>
private SysMessageState nextMessageStateAfterFailure(SysMessage _message, SysMessageFailCount _countOfFailedExecutionAttempts)
{
    SysMessageTarget messageTarget = SysMessageTarget::find(_message.MessageTarget);
    SysMessageTargetInstanceTypeMetadata messageTargetInstanceType = SysMessageTargetInstanceTypeMetadata::construct(messageTarget.InstanceRelationType);
    CompanyId companyId = messageTargetInstanceType.getCompanyId(messageTarget);
    SysMessageTypeMetadata messageTypeMetadata = SysMessageTypeMetadata::construct(_message.MessageType);

    if (companyId && CompanyInfo::findDataArea(companyId))
    {
        changecompany (companyId)
        {
            return messageTypeMetadata.nextMessageStateAfterFailure(_message.Content, _countOfFailedExecutionAttempts);
        }
    }
    else
    {
        return messageTypeMetadata.nextMessageStateAfterFailure(_message.Content, _countOfFailedExecutionAttempts);
    }
}
